7: public final class BoundedContextIsolationRules {
8: 
9:     private BoundedContextIsolationRules() {
10:     }
11: 
12:     public static ArchRule noCrossContextInternalAccess(String sourceContext, String targetContext) {
13:         String sourcePkg = "com.example.app." + sourceContext + "..";
14:         String targetRepoPkg = "com.example.app." + targetContext + ".repository..";
15:         String targetEntityPkg = "com.example.app." + targetContext + ".entity..";
16:         String targetDomainPkg = "com.example.app." + targetContext + ".domain..";
17:         return noClasses()
18:                 .that().resideInAPackage(sourcePkg)
19:                 .should().dependOnClassesThat()
20:                 .resideInAnyPackage(targetRepoPkg, targetEntityPkg, targetDomainPkg)
21:                 .because("bounded context '" + sourceContext + "' must not access internal repository, entity, "
22:                         + "or domain classes of '" + targetContext + "'")
23:                 .allowEmptyShould(true);
24:     }
25: }
